const express = require('express');
const fs = require('node:fs');
const path = require('node:path');
const { stagingAuth } = require('../middleware/stagingAuth');

const app = express();

app.get('/api/staging/vitest/snapshots/:suiteId/:testName', stagingAuth, (req, res) => {
  const { suiteId, testName } = req.params;

  // Verify that the requested test suite belongs to the caller's assigned tenant sandbox
  if (req.user.tenantSandboxId !== suiteId && req.user.role !== 'STAGING_SUPERADMIN') {
    return res.status(403).json({ error: 'Access denied to test snapshots of another tenant sandbox' });
  }

  const snapshotPath = path.resolve(__dirname, '../../tests/e2e/snapshots', suiteId, `${testName}.snap`);

  if (!fs.existsSync(snapshotPath)) {
    return res.status(404).json({ error: 'Snapshot not found' });
  }

  const snapshotContent = fs.readFileSync(snapshotPath, 'utf8');
  res.json({ suiteId, testName, snapshot: snapshotContent });
});

module.exports = app;
